import mongoose from "mongoose";

// Sub-schema for individual tasks generated by AI
const aiTaskSchema = new mongoose.Schema({
  title: { type: String, required: true },
  // 🟢 Description field permanently removed
  status: {
    type: String,
    enum: ["pending", "completed"],
    default: "pending",
  },
  createdAt: { type: Date, default: Date.now },
});

const aiPlanSchema = new mongoose.Schema(
  {
    user: { type: mongoose.Schema.Types.ObjectId, ref: "User", required: true },

    // 1. Data collected from the user's questionnaire
    intakeData: {
      primaryFocus: { type: String, required: true },
      challenges: [{ type: String }],
      durationDays: { type: Number, required: true, enum: [21, 60, 90] },
    },

    // 2. The AI's generated psychological roadmap
    aiStrategy: {
      corePhilosophy: { type: String },
      cognitiveReframes: [{ type: String }],
    },

    // 3. The actionable tasks (now title-only)
    dailyRoutines: [aiTaskSchema],
    weeklyMilestones: [aiTaskSchema],

    isActive: { type: Boolean, default: true },

    // 4. Progress tracking for adherence
    completionLog: [
      {
        date: { type: Date, default: Date.now },
        completedCount: { type: Number, default: 0 },
      },
    ],
  },
  { timestamps: true },
);

const AIPlan = mongoose.model("AIPlan", aiPlanSchema);
export default AIPlan;
